  builder_.add_DESIGNATION(DESIGNATION);
  builder_.add_NUMBER(NUMBER);
  builder_.add_PHA(PHA);
  builder_.add_NEO(NEO);
  builder_.add_ORBIT_CLASS(ORBIT_CLASS);
  return builder_.Finish();
