inline const SBD *GetSBD(const void *buf) {
  return ::flatbuffers::GetRoot<SBD>(buf);
}

inline const SBD *GetSizePrefixedSBD(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SBD>(buf);
}

inline const char *SBDIdentifier() {
  return "$SBD";
}

inline bool SBDBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SBDIdentifier());
}

inline bool SizePrefixedSBDBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SBDIdentifier(), true);
}

template <bool B = false>
inline bool VerifySBDBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SBD>(SBDIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSBDBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SBD>(SBDIdentifier());
}

inline void FinishSBDBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SBD> root) {
  fbb.Finish(root, SBDIdentifier());
}

inline void FinishSizePrefixedSBDBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SBD> root) {
  fbb.FinishSizePrefixed(root, SBDIdentifier());
}

